<set-variable name="ccofRequestFacts" value="@{
    try {
        var body = context.Request.Body.As(preserveContent: true);
        var model = body["model"];
        var stream = body["stream"];
        return new JObject(
            new JProperty("model", model != null && model.Type == JTokenType.String ? (string)model : ""),
            new JProperty("stream", stream != null && stream.Type == JTokenType.Boolean && (bool)stream)).ToString(Newtonsoft.Json.Formatting.None);
    } catch {
        return "";
    }
}" />






















    <set-variable name="ccofCachedDecisionValid" value="@{
        if (!context.Variables.ContainsKey("ccofCached")) { return false; }
        try {
            var body = JObject.Parse((string)context.Variables["ccofCached"])["d"] as JObject;
            if (body == null || body["decisionVersion"] == null || body["decisionVersion"].Type != JTokenType.Integer || (long)body["decisionVersion"] != 3) { return false; }
            var idPattern = "^[A-Za-z0-9][A-Za-z0-9_-]{0,79}\\z";
            foreach (var field in new string[] { "projectId", "classification", "backendId" }) {
                var value = body[field];
                if (value == null || value.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)value, idPattern)) { return false; }
            }
            var groupId = body["classificationGroupId"];
            if (groupId == null || groupId.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)groupId, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\\z")) { return false; }
            var route = body["routeBackendId"];
            if (route != null && (route.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)route, "^ccof-pool-[a-z0-9-]{1,50}-r[0-9]{1,9}\\z"))) { return false; }
            var familyPolicy = body["familyPolicy"] as JObject;
            if (familyPolicy == null || familyPolicy.Count != 2) { return false; }
            var aggregate = familyPolicy["aggregateLimits"] as JObject;
            var families = familyPolicy["families"] as JObject;
            if (aggregate == null || aggregate.Count != 2 || families == null || families.Count == 0) { return false; }
            var scopes = new System.Collections.Generic.List();
            scopes.Add(aggregate["person"] as JObject);
            scopes.Add(aggregate["group"] as JObject);
            var registered = new System.Collections.Generic.HashSet(StringComparer.Ordinal);
            foreach (var family in families.Properties()) {
                if (Array.IndexOf(new string[] { "haiku", "sonnet", "opus", "fable", "mythos" }, family.Name) < 0) { return false; }
                if ((family.Name == "fable" || family.Name == "mythos") && (string)body["classification"] != "CYB") { return false; }
                var entry = family.Value as JObject;
                if (entry == null || entry.Count != 3) { return false; }
                var models = entry["models"] as JArray;
                if (models == null || models.Count == 0) { return false; }
                foreach (var model in models) {
                    if (model.Type != JTokenType.String) { return false; }
                    var text = (string)model;
                    if (!System.Text.RegularExpressions.Regex.IsMatch(text, "^[A-Za-z0-9][A-Za-z0-9._-]{0,119}\\z") || !registered.Add(text)) { return false; }
                    if (text.StartsWith("claude-", StringComparison.Ordinal)) {
                        var canonical = System.Text.RegularExpressions.Regex.Match(text, "^claude-(haiku|sonnet|opus|fable|mythos)-[A-Za-z0-9][A-Za-z0-9._-]{0,105}\\z");
                        if (!canonical.Success || canonical.Groups[1].Value != family.Name) { return false; }
                    }
                }
                scopes.Add(entry["person"] as JObject);
                scopes.Add(entry["group"] as JObject);
            }
            var periods = new string[] { "Hourly", "Daily", "Weekly", "Monthly", "Yearly" };
            foreach (var scope in scopes) {
                if (scope == null || scope.Count != 3 || scope.Property("tokensPerMinute") == null || scope.Property("tokenQuota") == null || scope.Property("tokenQuotaPeriod") == null) { return false; }
                var tpm = scope["tokensPerMinute"];
                var quota = scope["tokenQuota"];
                var period = scope["tokenQuotaPeriod"];
                if (tpm.Type != JTokenType.Null && (tpm.Type != JTokenType.Integer || (long)tpm < 1 || (long)tpm > int.MaxValue)) { return false; }
                if (quota.Type != JTokenType.Null && (quota.Type != JTokenType.Integer || (long)quota < 1 || (long)quota > 9007199254740991L)) { return false; }
                if (period.Type != JTokenType.Null && (period.Type != JTokenType.String || Array.IndexOf(periods, (string)period) < 0)) { return false; }
                if ((quota.Type == JTokenType.Null) != (period.Type == JTokenType.Null)) { return false; }
            }
            return true;
        } catch {
            return false;
        }
    }" />
    <set-variable name="ccofCacheState" value="@{
        if (!context.Variables.ContainsKey("ccofCached")) { return "miss"; }
        try {
            var entry = JObject.Parse((string)context.Variables["ccofCached"]);
            var now = DateTime.UtcNow.Ticks / 10000000;
            var age = now - (long)entry["at"];
            var kind = (string)entry["k"];
            if (age < 0) { return "miss"; }
            if (kind == "allow") {
                if (!(bool)context.Variables["ccofCachedDecisionValid"]) { return "miss"; }
                if (age >= %%ALLOW_TTL%% + %%LKG_GRACE%%) { return "miss"; }
                if (age < %%ALLOW_TTL%%) { return "fresh-allow"; }
                var retryAt = entry["rt"];
                return retryAt != null && retryAt.Type == JTokenType.Integer && now < (long)retryAt ? "stale-allow-backoff" : "stale-allow";
            }
            if (kind == "refuse") { return age < %%REFUSAL_TTL%% ? "fresh-refusal" : "miss"; }
            return "miss";
        } catch {
            return "miss";
        }
    }" />



































            %%RESOLVER_URL%%
            POST

              application/json


              @("Bearer " + (string)context.Variables["ccofResolverToken"])

            @{
                var body = new JObject(
                    new JProperty("personId", (string)context.Variables["ccofOid"]),
                    new JProperty("requestId", context.RequestId.ToString()));
                var selector = (string)context.Variables["ccofSelector"];
                if (selector != "") { body["projectId"] = selector; }
                return body.ToString(Newtonsoft.Json.Formatting.None);
            }






    <set-variable name="ccofResolverResult" value="@{
        var unavailable = new JObject(new JProperty("o", "unavailable")).ToString(Newtonsoft.Json.Formatting.None);
        var response = context.Variables.ContainsKey("ccofResolverResponse") ? context.Variables["ccofResolverResponse"] as IResponse : null;
        if (response == null) { return unavailable; }
        try {
            var body = response.Body.As();
            if (body == null) { return unavailable; }
            var outcome = body["resolverOutcome"] != null && body["resolverOutcome"].Type == JTokenType.String ? (string)body["resolverOutcome"] : "";
            var error = body["error"] != null && body["error"].Type == JTokenType.String ? (string)body["error"] : "";
            var budget = body["budgetState"] != null && body["budgetState"].Type == JTokenType.String ? (string)body["budgetState"] : "";
            if (budget != "fresh" && budget != "degraded" && budget != "stale" && budget != "missing") { budget = ""; }
            var idPattern = "^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$";
            var refusedProject = body["projectId"] != null && body["projectId"].Type == JTokenType.String && System.Text.RegularExpressions.Regex.IsMatch((string)body["projectId"], idPattern) ? (string)body["projectId"] : "";
            var refusedClassification = body["classification"] != null && body["classification"].Type == JTokenType.String && System.Text.RegularExpressions.Regex.IsMatch((string)body["classification"], idPattern) ? (string)body["classification"] : "";
            if (outcome == "refused" && response.StatusCode == 403 && (error == "budget_exhausted" || error == "aggregate_budget_exhausted")) {
                return new JObject(new JProperty("o", "refuse"), new JProperty("r", "refused"), new JProperty("c", error), new JProperty("b", budget), new JProperty("rp", refusedProject), new JProperty("rc", refusedClassification)).ToString(Newtonsoft.Json.Formatting.None);
            }
            if (outcome == "refused" && response.StatusCode == 403) {
                return new JObject(new JProperty("o", "refuse"), new JProperty("r", "refused"), new JProperty("c", "not_authorized"), new JProperty("b", budget)).ToString(Newtonsoft.Json.Formatting.None);
            }
            if (outcome == "refused" && response.StatusCode == 400 && error == "project_selection_required") {
                return new JObject(new JProperty("o", "refuse"), new JProperty("r", "refused"), new JProperty("c", "project_selection_required"), new JProperty("b", budget)).ToString(Newtonsoft.Json.Formatting.None);
            }
            if (response.StatusCode == 503 && (budget == "stale" || budget == "missing")) {
                return new JObject(new JProperty("o", "refuse"), new JProperty("r", "unavailable"), new JProperty("c", "budget_state_unavailable"), new JProperty("b", budget)).ToString(Newtonsoft.Json.Formatting.None);
            }
            if (response.StatusCode != 200 || (outcome != "success" && outcome != "degraded")) { return unavailable; }
            if (body["decisionVersion"] == null || body["decisionVersion"].Type != JTokenType.Integer || (long)body["decisionVersion"] != 3) { return unavailable; }
            var decision = new JObject();
            foreach (var field in new string[] { "projectId", "classification", "backendId" }) {
                var value = body[field];
                if (value == null || value.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)value, idPattern)) { return unavailable; }
                decision[field] = (string)value;
            }
            var groupId = body["classificationGroupId"];
            if (groupId == null || groupId.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)groupId, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\\z")) { return unavailable; }
            var route = body["routeBackendId"];
            if (route != null && (route.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)route, "^ccof-pool-[a-z0-9-]{1,50}-r[0-9]{1,9}\\z"))) { return unavailable; }
            var familyPolicy = body["familyPolicy"] as JObject;
            if (familyPolicy == null || familyPolicy.Count != 2) { return unavailable; }
            var aggregate = familyPolicy["aggregateLimits"] as JObject;
            var families = familyPolicy["families"] as JObject;
            if (aggregate == null || aggregate.Count != 2 || families == null || families.Count == 0) { return unavailable; }
            var scopes = new System.Collections.Generic.List();
            scopes.Add(aggregate["person"] as JObject);
            scopes.Add(aggregate["group"] as JObject);
            var registered = new System.Collections.Generic.HashSet(StringComparer.Ordinal);
            foreach (var family in families.Properties()) {
                if (Array.IndexOf(new string[] { "haiku", "sonnet", "opus", "fable", "mythos" }, family.Name) < 0) { return unavailable; }
                if ((family.Name == "fable" || family.Name == "mythos") && (string)body["classification"] != "CYB") { return unavailable; }
                var entry = family.Value as JObject;
                if (entry == null || entry.Count != 3) { return unavailable; }
                var models = entry["models"] as JArray;
                if (models == null || models.Count == 0) { return unavailable; }
                foreach (var model in models) {
                    if (model.Type != JTokenType.String) { return unavailable; }
                    var text = (string)model;
                    if (!System.Text.RegularExpressions.Regex.IsMatch(text, "^[A-Za-z0-9][A-Za-z0-9._-]{0,119}\\z") || !registered.Add(text)) { return unavailable; }
                    if (text.StartsWith("claude-", StringComparison.Ordinal)) {
                        var canonical = System.Text.RegularExpressions.Regex.Match(text, "^claude-(haiku|sonnet|opus|fable|mythos)-[A-Za-z0-9][A-Za-z0-9._-]{0,105}\\z");
                        if (!canonical.Success || canonical.Groups[1].Value != family.Name) { return unavailable; }
                    }
                }
                scopes.Add(entry["person"] as JObject);
                scopes.Add(entry["group"] as JObject);
            }
            var periods = new string[] { "Hourly", "Daily", "Weekly", "Monthly", "Yearly" };
            foreach (var scope in scopes) {
                if (scope == null || scope.Count != 3 || scope.Property("tokensPerMinute") == null || scope.Property("tokenQuota") == null || scope.Property("tokenQuotaPeriod") == null) { return unavailable; }
                var tpm = scope["tokensPerMinute"];
                var quota = scope["tokenQuota"];
                var period = scope["tokenQuotaPeriod"];
                if (tpm.Type != JTokenType.Null && (tpm.Type != JTokenType.Integer || (long)tpm < 1 || (long)tpm > int.MaxValue)) { return unavailable; }
                if (quota.Type != JTokenType.Null && (quota.Type != JTokenType.Integer || (long)quota < 1 || (long)quota > 9007199254740991L)) { return unavailable; }
                if (period.Type != JTokenType.Null && (period.Type != JTokenType.String || Array.IndexOf(periods, (string)period) < 0)) { return unavailable; }
                if ((quota.Type == JTokenType.Null) != (period.Type == JTokenType.Null)) { return unavailable; }
            }
            decision["decisionVersion"] = 3;
            decision["classificationGroupId"] = ((string)groupId).ToLowerInvariant();
            decision["familyPolicy"] = familyPolicy;
            var displayName = body["classificationGroupDisplayName"];
            if (displayName != null && displayName.Type == JTokenType.String && ((string)displayName).Length >= 1 && ((string)displayName).Length <= 256) {
                decision["classificationGroupDisplayName"] = (string)displayName;
            }
            // ADR 0034: an optional project-scoped APIM pool, validated above like the cached copy.
            if (route != null) { decision["routeBackendId"] = (string)route; }
            // ADR 0035: the per-minute ceiling of the reconciler, kept with the cached decision. Anything but a
            // whole number in int range is dropped, which leaves the family limits as the only token limits.
            var ceiling = body["personCeilingTokensPerMinute"];
            if (ceiling != null && ceiling.Type == JTokenType.Integer && (long)ceiling >= 0 && (long)ceiling <= 2147483647) {
                decision["personCeilingTokensPerMinute"] = (long)ceiling;
            }
            var descriptor = body["backend"];
            if (descriptor != null && descriptor.Type != JTokenType.Null) {
                var backend = descriptor as JObject;
                if (backend == null || backend["id"] == null || backend["id"].Type != JTokenType.String || (string)backend["id"] != (string)decision["backendId"]) { return unavailable; }
                if (backend["apiFormat"] == null || backend["apiFormat"].Type != JTokenType.String || (string)backend["apiFormat"] != "anthropic-messages") { return unavailable; }
                var auth = backend["auth"] as JObject;
                var mode = auth != null && auth["mode"] != null && auth["mode"].Type == JTokenType.String ? (string)auth["mode"] : "";
                var normalizedAuth = new JObject(new JProperty("mode", mode));
                if (mode == "managed-identity") {
                    var resource = auth["resource"];
                    if (resource == null || resource.Type != JTokenType.String) { return unavailable; }
                    var resourceText = (string)resource;
                    var resourceOk = System.Text.RegularExpressions.Regex.IsMatch(resourceText, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$");
                    if (!resourceOk && resourceText.Length <= 2048) {
                        var resourceUri = new Uri(resourceText);
                        resourceOk = resourceUri.Scheme == Uri.UriSchemeHttps || resourceUri.Scheme == "api";
                    }
                    if (!resourceOk) { return unavailable; }
                    normalizedAuth["resource"] = resourceText;
                } else if (mode == "credential-manager") {
                    foreach (var name in new string[] { "providerId", "connectionId" }) {
                        var reference = auth[name];
                        if (reference == null || reference.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)reference, idPattern)) { return unavailable; }
                        normalizedAuth[name] = (string)reference;
                    }
                } else if (mode != "backend-entity") {
                    return unavailable;
                }
                decision["auth"] = normalizedAuth;
            }
            return new JObject(new JProperty("o", "allow"), new JProperty("r", outcome), new JProperty("b", budget), new JProperty("d", decision)).ToString(Newtonsoft.Json.Formatting.None);
        } catch {
            return unavailable;
        }
    }" />




















        <set-variable name="ccofStoreSeconds" value="@{
            var left = %%ALLOW_TTL%% + %%LKG_GRACE%% - (DateTime.UtcNow.Ticks / 10000000 - (long)JObject.Parse((string)context.Variables["ccofCached"])["at"]);
            return left < 1 ? 1 : (int)left;
        }" />


















    <set-variable name="ccofClassificationGroupDisplayName" value="@{
        var name = JObject.Parse((string)context.Variables["ccofDecision"])["classificationGroupDisplayName"];
        return name != null && name.Type == JTokenType.String && ((string)name).Length >= 1 && ((string)name).Length <= 256 ? (string)name : "";
    }" />




    <set-variable name="ccofBudgetPaceTpm" value="@{
        var ceiling = JObject.Parse((string)context.Variables["ccofDecision"])["personCeilingTokensPerMinute"];
        return ceiling != null && ceiling.Type == JTokenType.Integer && (long)ceiling > 0 && (long)ceiling <= 2147483647 ? (int)(long)ceiling : 0;
    }" />










    <set-variable name="ccofModelFamily" value="@{
        var model = (string)context.Variables["ccofModel"];
        var classification = (string)context.Variables["ccofClassification"];
        var admitted = "";
        var matches = 0;
        foreach (var family in ((JObject)JObject.Parse((string)context.Variables["ccofFamilyPolicy"])["families"]).Properties()) {
            if (Array.IndexOf(new string[] { "haiku", "sonnet", "opus", "fable", "mythos" }, family.Name) < 0) { return ""; }
            if ((family.Name == "fable" || family.Name == "mythos") && classification != "CYB") { return ""; }
            foreach (var allowed in (JArray)family.Value["models"]) {
                if (allowed.Type == JTokenType.String && string.Equals((string)allowed, model, StringComparison.Ordinal)) {
                    admitted = family.Name;
                    matches++;
                }
            }
        }
        return matches == 1 ? admitted : "";
    }" />



















































































    %%ANTHROPIC_VERSION_DEFAULT%%

      %%BACKEND_BRANCHES%%













              @("Bearer " + ((Authorization)context.Variables["ccofBackendAuthContext"]).AccessToken)




















          @{
              var budget = (string)context.Variables["ccofResolverBudgetState"];
              return new JObject(
                  new JProperty("schemaVersion", 1),
                  new JProperty("requestId", context.RequestId.ToString()),
                  new JProperty("observedAt", DateTime.UtcNow.ToString("o")),
                  new JProperty("resolverOutcome", (string)context.Variables["ccofResolverOutcome"]),
                  new JProperty("resolverDurationMs", (long)context.Variables["ccofResolverMs"]),
                  new JProperty("budgetState", budget == "" ? null : budget),
                  new JProperty("served", false)).ToString(Newtonsoft.Json.Formatting.None);
