    <set-variable name="ccofRefusalBody" value="@{
        var code = (string)context.Variables["ccofRefusal"];
        var project = context.Variables.GetValueOrDefault("ccofProjectId", "");
        var classification = context.Variables.GetValueOrDefault("ccofClassification", "");
        var selector = (string)context.Variables["ccofSelector"];
        var model = (string)context.Variables["ccofModel"];
        string type;
        string message;
        switch (code) {
            case "token_identity_missing":
                type = "authentication_error";
                message = "The access token has no valid user object id (oid). Sign in to the gateway again.";
                break;
            case "token_scope_missing":
                type = "permission_error";
                message = "The access token does not carry this gateway's %%DELEGATED_SCOPE%% permission. Sign in again through your organisation's Claude sign-in.";
                break;
            case "token_client_not_allowed":
                type = "permission_error";
                message = "The access token was issued to an application this gateway does not accept. Sign in through your organisation's Claude sign-in.";
                break;
            case "app_token_not_allowed":
                type = "permission_error";
                message = "This gateway accepts a person's sign-in, not an application token. Sign in as yourself.";
                break;
            case "project_header_invalid":
                type = "invalid_request_error";
                message = "The %%PROJECT_HEADER%% header must be a project id: a letter or digit followed by up to 79 letters, digits, '_' or '-'.";
                break;
            case "request_body_invalid":
                type = "invalid_request_error";
                message = "The request body must be a JSON object.";
                break;
            case "request_model_missing":
                type = "invalid_request_error";
                message = "The request body must name a model in its 'model' field.";
                break;
            case "not_authorized":
                type = "permission_error";
                message = "You are not entitled to use Claude through this gateway" + (selector == "" ? "" : " for project " + selector) + ". Ask your platform team to add you to your project's Claude group.";
                break;
            case "project_selection_required":
                type = "invalid_request_error";
                message = "You belong to more than one project. Set the %%PROJECT_HEADER%% header to the id of the project this request is for.";
                break;
            case "budget_exhausted":
                type = "permission_error";
                message = "Your CCU budget" + (project == "" ? "" : " for project " + project) + " is used up for this budget period. Your access is otherwise unchanged; ask your platform team to raise the budget, or wait for the next period.";
                break;
            case "aggregate_budget_exhausted":
                type = "permission_error";
                message = "The CCU budget shared by classification " + (classification == "" ? "of your group" : classification) + (project == "" ? "" : " in project " + project) + " is used up for this budget period. Your own access is unchanged; ask your platform team to raise the budget, or wait for the next period.";
                break;
            case "model_family_not_allowed":
                type = "permission_error";
                message = "The requested model family is not available to your project classification. Ask your platform team for an approved model.";
                break;
            case "entitlement_unavailable":
                type = "api_error";
                message = "The gateway could not confirm your access just now. This is not a problem with your access. Retry in %%RETRY_AFTER%% seconds.";
                break;
            case "backend_credential_unavailable":
                type = "api_error";
                message = "The gateway could not get a credential for the model service. Your access is unaffected. Retry in %%RETRY_AFTER%% seconds; if this continues, tell your platform team.";
                break;
            case "budget_state_unavailable":
                type = "api_error";
                message = "The budget state for your project could not be confirmed, so this request cannot be admitted now. This is not about your access. Retry in %%RETRY_AFTER%% seconds; if this continues, tell your platform team.";
                break;
            case "backend_not_configured":
                type = "api_error";
                message = "The model service for project " + project + " is not configured on this gateway. Your access is unaffected; tell your platform team.";
                break;
            default:
                type = "api_error";
                message = "The gateway refused the request.";
                break;
        }
        return new JObject(
            new JProperty("type", "error"),
            new JProperty("error", new JObject(
                new JProperty("type", type),
                new JProperty("message", message + " Request id: " + context.RequestId.ToString() + ".")))).ToString(Newtonsoft.Json.Formatting.None);
    }" />





